function hashStringFNV1a(input) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function hashStateObject(value) {
  try {
    return hashStringFNV1a(JSON.stringify(value));
  } catch (_error) {
    return "";
  }
}


function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function parseIsoDate(iso) {
  if (!iso) {
    return null;
  }
  const [year, month, day] = String(iso).split("-").map(Number);
  if (!year || !month || !day) {
    return null;
  }
  return new Date(year, month - 1, day);
}

function toIsoDate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function addDays(iso, days) {
  const value = parseIsoDate(iso);
  value.setDate(value.getDate() + days);
  return toIsoDate(value);
}


function formatShortDateLabel(value = new Date()) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  return date.toLocaleDateString("de-DE", {
    day: "2-digit",
    month: "2-digit",
    year: "2-digit"
  });
}

function formatLongDateLabel(value = new Date()) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  return date.toLocaleDateString("de-DE", {
    day: "numeric",
    month: "long",
    year: "numeric"
  });
}

function parseShortDateLabel(value) {
  const match = String(value || "").trim().match(/^(\d{2})\.(\d{2})\.(\d{2})$/);
  if (!match) {
    return null;
  }
  const day = Number(match[1]);
  const month = Number(match[2]);
  const year = 2000 + Number(match[3]);
  if (!day || !month) {
    return null;
  }
  const date = new Date(year, month - 1, day);
  if (
    Number.isNaN(date.getTime())
    || date.getFullYear() !== year
    || date.getMonth() !== month - 1
    || date.getDate() !== day
  ) {
    return null;
  }
  return date;
}

function dayOfWeekIso(iso) {
  const value = parseIsoDate(iso);
  const weekday = value.getDay();
  return weekday === 0 ? 7 : weekday;
}

function isSchoolWeekdayIso(iso) {
  const weekday = dayOfWeekIso(iso);
  return weekday >= 1 && weekday <= 5;
}

function normalizeIsoToSchoolWeekday(iso, direction = "forward") {
  if (!iso) {
    return iso;
  }
  let current = iso;
  const step = direction === "backward" ? -1 : 1;
  let guard = 0;
  while (!isSchoolWeekdayIso(current) && guard < 7) {
    current = addDays(current, step);
    guard += 1;
  }
  return current;
}

function weekStartFor(iso) {
  const value = parseIsoDate(iso);
  const weekday = dayOfWeekIso(iso);
  value.setDate(value.getDate() - (weekday - 1));
  return toIsoDate(value);
}

















function suggestColor(existingColors) {
  const existing = new Set(
    existingColors
      .map((item) => canonicalHexColor(item))
      .filter(Boolean)
      .map((item) => item.toLowerCase())
  );
  for (const color of COLOR_PALETTE) {
    const normalized = normalizeHexColor(color, DEFAULT_COURSE_COLOR);
    if (!existing.has(normalized.toLowerCase())) {
      return normalized;
    }
  }
  return normalizeHexColor(
    COLOR_PALETTE[existing.size % COLOR_PALETTE.length],
    DEFAULT_COURSE_COLOR
  );
}

function canonicalHexColor(color) {
  const value = String(color || "").trim();
  const match = value.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
  if (!match) {
    return null;
  }
  const hex = match[1].toUpperCase();
  if (hex.length === 3) {
    return `#${hex[0]}${hex[0]}${hex[1]}${hex[1]}${hex[2]}${hex[2]}`;
  }
  return `#${hex}`;
}

function normalizeHexColor(color, fallback = DEFAULT_COURSE_COLOR) {
  const normalized = canonicalHexColor(color);
  if (normalized) {
    return normalized;
  }
  const fallbackColor = canonicalHexColor(fallback);
  return fallbackColor || DEFAULT_COURSE_COLOR;
}

function normalizeCourseColor(color, noLesson = false) {
  if (noLesson) {
    return NO_LESSON_COLOR;
  }
  return normalizeHexColor(color, DEFAULT_COURSE_COLOR);
}

function hexToRgb(color) {
  const normalized = canonicalHexColor(color);
  if (!normalized) {
    return null;
  }
  const hex = normalized.slice(1);
  return {
    r: parseInt(hex.slice(0, 2), 16),
    g: parseInt(hex.slice(2, 4), 16),
    b: parseInt(hex.slice(4, 6), 16)
  };
}

function colorToRgba(color, alpha) {
  const rgb = hexToRgb(color) || hexToRgb(DEFAULT_COURSE_COLOR);
  return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${clamp(Number(alpha) || 1, 0, 1)})`;
}

function lightenHex(color, amount = 0.1) {
  const rgb = hexToRgb(color) || hexToRgb(DEFAULT_COURSE_COLOR);
  const factor = clamp(Number(amount) || 0, 0, 1);
  const blend = (value) => Math.round(value + ((255 - value) * factor));
  const r = blend(rgb.r);
  const g = blend(rgb.g);
  const b = blend(rgb.b);
  const toHex = (value) => value.toString(16).padStart(2, "0");
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

function readableTextColor(color) {
  const rgb = hexToRgb(color) || hexToRgb(DEFAULT_COURSE_COLOR);
  const luminance = ((0.2126 * rgb.r) + (0.7152 * rgb.g) + (0.0722 * rgb.b)) / 255;
  return luminance > 0.62 ? "#0f1216" : "#f8fafc";
}


function normalizeGradeTextPart(value) {
  return String(value || "").trim().replace(/\s+/g, " ");
}

function normalizeGradeOccurrenceCategoryEmoji(value) {
  const source = String(value ?? "").trim();
  if (!source) return "";
  const match = source.match(/(?:\p{Regional_Indicator}{2}|\p{Extended_Pictographic}(?:\uFE0F|\p{Emoji_Modifier})?(?:\u200D\p{Extended_Pictographic}(?:\uFE0F|\p{Emoji_Modifier})?)*)/u);
  return match ? match[0] : "";
}

function normalizeGradeOccurrenceCategoryPolarity(value) {
  return String(value || "").trim().toLowerCase() === "positive" ? "positive" : "negative";
}

function normalizeGradePerformanceFlair(value) {
  const normalized = String(value || "").trim().toUpperCase();
  return GRADE_STUDENT_PERFORMANCE_FLAIRS.includes(normalized) ? normalized : "";
}

function buildGradeStudentNameMatchKey(lastName, firstName) {
  return [
    normalizeGradeTextPart(lastName).toLocaleLowerCase("de"),
    normalizeGradeTextPart(firstName).toLocaleLowerCase("de")
  ].join("|");
}


function compareGradeStudents(a, b) {
  const aLast = normalizeGradeTextPart(a && a.lastName);
  const bLast = normalizeGradeTextPart(b && b.lastName);
  const byLast = aLast.localeCompare(bLast, "de", { sensitivity: "base" });
  if (byLast !== 0) {
    return byLast;
  }
  const aFirst = normalizeGradeTextPart(a && a.firstName);
  const bFirst = normalizeGradeTextPart(b && b.firstName);
  const byFirst = aFirst.localeCompare(bFirst, "de", { sensitivity: "base" });
  if (byFirst !== 0) {
    return byFirst;
  }
  return Number(a && a.id || 0) - Number(b && b.id || 0);
}

function compareGradeStudentsByNameOrder(a, b, order = "last") {
  if (normalizeGradeStudentNameOrder(order) !== "first") {
    return compareGradeStudents(a, b);
  }
  const aFirst = normalizeGradeTextPart(a && a.firstName);
  const bFirst = normalizeGradeTextPart(b && b.firstName);
  const byFirst = aFirst.localeCompare(bFirst, "de", { sensitivity: "base" });
  if (byFirst !== 0) {
    return byFirst;
  }
  const aLast = normalizeGradeTextPart(a && a.lastName);
  const bLast = normalizeGradeTextPart(b && b.lastName);
  const byLast = aLast.localeCompare(bLast, "de", { sensitivity: "base" });
  if (byLast !== 0) {
    return byLast;
  }
  return Number(a && a.id || 0) - Number(b && b.id || 0);
}

function normalizeGradeNumber(value, fallback = 1) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return Number(fallback) > 0 ? Number(fallback) : 1;
  }
  return parsed;
}

function normalizeGradeInteger(value, fallback = 1) {
  return Math.max(1, Math.round(normalizeGradeNumber(value, fallback)));
}

function formatGradeAssessmentDisplayTitle(title) {
  const text = normalizeGradeTextPart(title);
  if (!text) {
    return "";
  }
  const dottedDateMatch = text.match(/\b(\d{1,2})\.(\d{1,2})(?:\.(\d{2,4}))?\b/);
  if (dottedDateMatch) {
    const day = String(Number(dottedDateMatch[1]) || 0).padStart(2, "0");
    const month = String(Number(dottedDateMatch[2]) || 0).padStart(2, "0");
    if (day !== "00" && month !== "00") {
      return `${day}.${month}.`;
    }
  }
  const isoDateMatch = text.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
  if (isoDateMatch) {
    const day = String(Number(isoDateMatch[3]) || 0).padStart(2, "0");
    const month = String(Number(isoDateMatch[2]) || 0).padStart(2, "0");
    if (day !== "00" && month !== "00") {
      return `${day}.${month}.`;
    }
  }
  return text;
}

function buildGradeAssessmentDisplayTitleMarkup(title) {
  const displayTitle = formatGradeAssessmentDisplayTitle(title);
  const dateMatch = displayTitle.match(/^(\d{2}\.)(\d{2}\.)$/);
  if (dateMatch) {
    return `${escapeHtml(dateMatch[1])}<br>${escapeHtml(dateMatch[2])}`;
  }
  return escapeHtml(displayTitle);
}

function shouldShowGradeWeight(weight) {
  return Math.abs(normalizeGradeStructureWeight(weight, 1) - 1) > 0.0000001;
}

function formatGradeWeightValue(weight) {
  return String(normalizeGradeStructureWeight(weight, 1)).replace(".", ",");
}

function formatGradeWeightPercentSuffix(weight) {
  return shouldShowGradeWeight(weight)
    ? ` (${formatGradeWeightValue(weight)}%)`
    : "";
}

function buildGradeAssessmentWeightMarkup(weight, mode = "grade") {
  if (normalizeGradeAssessmentMode(mode) === "homework") {
    return "";
  }
  if (!shouldShowGradeWeight(weight)) {
    return "";
  }
  return `<span class="grade-assessment-meta"><span class="grade-assessment-weight-icon" aria-hidden="true">⚖️</span> ${escapeHtml(formatGradeWeightValue(weight))}</span>`;
}

function buildGradeAssessmentOccurrenceEmojiMarkup(mode, emoji) {
  if (normalizeGradeAssessmentMode(mode) !== "homework") {
    return "";
  }
  const normalizedEmoji = normalizeGradeOccurrenceCategoryEmoji(emoji);
  if (!normalizedEmoji) {
    return "";
  }
  return `<span class="grade-assessment-meta"><span class="grade-assessment-occurrence-icon" aria-hidden="true">${escapeHtml(normalizedEmoji)}</span></span>`;
}

function isWeightedGradeAssessmentMode(mode) {
  const normalized = normalizeGradeAssessmentMode(mode);
  return normalized === "grade" || normalized === "test";
}

function normalizeGradeHalfYear(value) {
  return String(value || "").trim().toLowerCase() === "h2" ? "h2" : "h1";
}

const GRADE_TEST_SCALE_DEFAULT = "sek2";
const GRADE_TEST_SCALE_CUSTOM = "custom";
const GRADE_TEST_SCALE_IDS = ["sek1", "sek2", GRADE_TEST_SCALE_CUSTOM];
const GRADE_TEST_SCALE_GRADES = Array.from({ length: 16 }, (_item, index) => 15 - index);
const GRADE_OCCURRENCE_CATEGORY_SUGGESTIONS = Object.freeze([
  { emoji: "🏠", name: "Hausaufgaben fehlen", polarity: "negative" },
  { emoji: "🎒", name: "Material fehlt", polarity: "negative" },
  { emoji: "🕒", name: "Verspätung", polarity: "negative" },
  { emoji: "📱", name: "Gerätenutzung unpassend", polarity: "negative" },
  { emoji: "🤫", name: "Störung", polarity: "negative" },
  { emoji: "🙋", name: "Gutes Arbeitsverhalten", polarity: "positive" },
  { emoji: "👥", name: "Gutes Sozialverhalten", polarity: "positive" }
]);
const GRADE_DEFICIT_THRESHOLD_DEFAULT = 4;
const GRADE_TEST_SCALE_THRESHOLDS = {
  sek1: [
    [0.96, 15], [0.92, 14], [0.88, 13], [0.83, 12],
    [0.78, 11], [0.73, 10], [0.68, 9], [0.63, 8],
    [0.58, 7], [0.54, 6], [0.5, 5], [0.44, 4],
    [0.38, 3], [0.32, 2], [0.2, 1], [0, 0]
  ],
  sek2: [
    [0.95, 15], [0.9, 14], [0.85, 13], [0.8, 12],
    [0.75, 11], [0.7, 10], [0.65, 9], [0.6, 8],
    [0.55, 7], [0.5, 6], [0.45, 5], [0.4, 4],
    [0.33, 3], [0.27, 2], [0.2, 1], [0, 0]
  ]
};
GRADE_TEST_SCALE_THRESHOLDS[GRADE_TEST_SCALE_CUSTOM] = GRADE_TEST_SCALE_THRESHOLDS[GRADE_TEST_SCALE_DEFAULT];

function getGradeTestScaleDefaultLabel(scale = GRADE_TEST_SCALE_DEFAULT) {
  const normalized = normalizeGradeTestScale(scale);
  if (normalized === "sek1") {
    return "Sek I";
  }
  if (normalized === GRADE_TEST_SCALE_CUSTOM) {
    return "";
  }
  return "Sek II";
}

function cloneGradeTestThresholds(thresholds = GRADE_TEST_SCALE_THRESHOLDS[GRADE_TEST_SCALE_DEFAULT]) {
  return (Array.isArray(thresholds) ? thresholds : GRADE_TEST_SCALE_THRESHOLDS[GRADE_TEST_SCALE_DEFAULT])
    .map(([threshold, grade]) => [Number(threshold) || 0, clamp(Math.round(Number(grade) || 0), 0, 15)]);
}

function normalizeGradeAssessmentMode(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "homework" || normalized === "test") {
    return normalized;
  }
  return "grade";
}

function normalizeGradeAssessmentYearLevel(value) {
  const text = String(value ?? "").trim();
  if (!text) {
    return null;
  }
  const parsed = Math.round(Number(text));
  return parsed >= 5 && parsed <= 13 ? parsed : null;
}

function isGradeAssessmentCourseLevelDisabled(yearLevel) {
  const normalized = normalizeGradeAssessmentYearLevel(yearLevel);
  return normalized === null || normalized < 12;
}

function normalizeGradeAssessmentCourseLevel(value, yearLevel = null) {
  if (isGradeAssessmentCourseLevelDisabled(yearLevel)) {
    return "";
  }
  const normalized = String(value || "").trim().toLowerCase();
  return normalized === "gk" || normalized === "lk" ? normalized : "";
}

function normalizeGradeAssessmentNumber(value) {
  const text = String(value ?? "").replace(/\D+/g, "").slice(0, 2);
  return text ? Number(text) : null;
}

function formatGradeAssessmentNumber(value) {
  const normalized = normalizeGradeAssessmentNumber(value);
  return normalized === null ? "" : String(normalized);
}

function normalizeGradeAssessmentTopic(value) {
  return String(value || "").replace(/\r\n?/g, "\n").trim();
}

function normalizeGradeAssessmentExamDurationMinutes(value) {
  const text = String(value ?? "").replace(/\D+/g, "").slice(0, 3);
  if (!text) {
    return null;
  }
  const parsed = Math.round(Number(text));
  return parsed >= 1 && parsed <= 999 ? parsed : null;
}

function normalizeGradeAssessmentExpectationHorizonTemplateFile(value = null) {
  if (!value || typeof value !== "object" || !value.bytes) {
    return null;
  }
  const sourceBytes = value.bytes instanceof Uint8Array
    ? value.bytes
    : (Array.isArray(value.bytes) ? value.bytes : []);
  const bytes = Array.from(sourceBytes)
    .map((byte) => clamp(Math.round(Number(byte) || 0), 0, 255));
  if (!bytes.length) {
    return null;
  }
  return {
    name: String(value.name || EXPECTATION_HORIZON_TEMPLATE_FILE_NAME),
    bytes
  };
}

function normalizeGradeTestScale(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "sek1" || normalized === GRADE_TEST_SCALE_CUSTOM) {
    return normalized;
  }
  return GRADE_TEST_SCALE_DEFAULT;
}

function getGradeDeficitThresholdDefaultForScale(scale = GRADE_TEST_SCALE_DEFAULT) {
  return normalizeGradeTestScale(scale) === "sek1" ? 3 : GRADE_DEFICIT_THRESHOLD_DEFAULT;
}

function getDefaultGradeTestPredicateSuffixes(scale = GRADE_TEST_SCALE_DEFAULT) {
  return normalizeGradeTestScale(scale) !== "sek1";
}

function normalizeGradeTestPredicateSuffixes(value, fallback = true) {
  if (value === true || value === false) {
    return value;
  }
  if (value === 1 || value === "1") {
    return true;
  }
  if (value === 0 || value === "0") {
    return false;
  }
  const text = String(value ?? "").trim().toLowerCase();
  if (text === "true" || text === "yes" || text === "ja" || text === "on") {
    return true;
  }
  if (text === "false" || text === "no" || text === "nein" || text === "off") {
    return false;
  }
  return Boolean(fallback);
}

function applyGradeTestPredicateSuffixes(value, enabled = true) {
  if (value === null || value === undefined || value === "") {
    return null;
  }
  const grade = clamp(Math.round(Number(value) || 0), 0, 15);
  if (normalizeGradeTestPredicateSuffixes(enabled, true) || grade === 0) {
    return grade;
  }
  return Math.max(0, (Math.floor((grade - 1) / 3) * 3) + 2);
}

function normalizeGradeTestThresholds(thresholds = null, fallback = null) {
  const fallbackThresholds = cloneGradeTestThresholds(
    fallback || GRADE_TEST_SCALE_THRESHOLDS[GRADE_TEST_SCALE_DEFAULT]
  );
  const fallbackByGrade = new Map(fallbackThresholds.map(([threshold, grade]) => [Number(grade), Number(threshold)]));
  const source = Array.isArray(thresholds) ? thresholds : [];
  const sourceByGrade = new Map();
  source.forEach((entry, index) => {
    let threshold;
    let grade;
    if (Array.isArray(entry)) {
      threshold = entry[0];
      grade = entry[1];
    } else if (entry && typeof entry === "object") {
      threshold = entry.threshold;
      grade = entry.grade;
    }
    const normalizedGrade = clamp(Math.round(Number(grade ?? (15 - index)) || 0), 0, 15);
    const numericThreshold = Number(threshold);
    if (Number.isFinite(numericThreshold)) {
      sourceByGrade.set(normalizedGrade, clamp(numericThreshold, 0, 1));
    }
  });
  return GRADE_TEST_SCALE_GRADES.map((grade) => {
    const threshold = grade === 0
      ? 0
      : (
        sourceByGrade.has(grade)
          ? sourceByGrade.get(grade)
          : (fallbackByGrade.has(grade) ? fallbackByGrade.get(grade) : 0)
      );
    return [Number(threshold) || 0, grade];
  });
}

function buildDefaultGradeTestScaleSettings() {
  return {
    sek1: {
      id: "sek1",
      label: "Sek I",
      thresholds: cloneGradeTestThresholds(GRADE_TEST_SCALE_THRESHOLDS.sek1)
    },
    sek2: {
      id: "sek2",
      label: "Sek II",
      thresholds: cloneGradeTestThresholds(GRADE_TEST_SCALE_THRESHOLDS.sek2)
    },
    custom: {
      id: GRADE_TEST_SCALE_CUSTOM,
      label: "",
      thresholds: cloneGradeTestThresholds(GRADE_TEST_SCALE_THRESHOLDS[GRADE_TEST_SCALE_DEFAULT])
    }
  };
}

function normalizeGradeTestScaleTemplate(rawTemplate = null, scale = GRADE_TEST_SCALE_DEFAULT, fallback = null) {
  const normalizedScale = normalizeGradeTestScale(scale);
  const source = rawTemplate && typeof rawTemplate === "object" ? rawTemplate : {};
  const fallbackTemplate = fallback && typeof fallback === "object"
    ? fallback
    : buildDefaultGradeTestScaleSettings()[normalizedScale];
  const fixedLabel = normalizedScale === "sek1"
    ? "Sek I"
    : (normalizedScale === "sek2" ? "Sek II" : "");
  const rawLabel = normalizedScale === GRADE_TEST_SCALE_CUSTOM
    ? normalizeGradeTextPart(source.label).slice(0, 40)
    : fixedLabel;
  return {
    id: normalizedScale,
    label: rawLabel,
    thresholds: normalizeGradeTestThresholds(source.thresholds, fallbackTemplate.thresholds)
  };
}

function normalizeGradeTestScaleSettings(rawSettings = null) {
  const defaults = buildDefaultGradeTestScaleSettings();
  const source = rawSettings && typeof rawSettings === "object" ? rawSettings : {};
  return {
    sek1: normalizeGradeTestScaleTemplate(source.sek1, "sek1", defaults.sek1),
    sek2: normalizeGradeTestScaleTemplate(source.sek2, "sek2", defaults.sek2),
    custom: normalizeGradeTestScaleTemplate(source.custom, GRADE_TEST_SCALE_CUSTOM, defaults.custom)
  };
}

function getGradeTestScaleTemplate(settings = null, scale = GRADE_TEST_SCALE_DEFAULT) {
  const normalizedSettings = normalizeGradeTestScaleSettings(settings);
  const normalizedScale = normalizeGradeTestScale(scale);
  return normalizedSettings[normalizedScale] || normalizedSettings[GRADE_TEST_SCALE_DEFAULT];
}

function listVisibleGradeTestScaleTemplates(settings = null) {
  const normalized = normalizeGradeTestScaleSettings(settings);
  const templates = [normalized.sek1, normalized.sek2];
  if (String(normalized.custom.label || "").trim()) {
    templates.push(normalized.custom);
  }
  return templates;
}

function buildGradeTestScaleSnapshot(settings = null, scale = GRADE_TEST_SCALE_DEFAULT) {
  const template = getGradeTestScaleTemplate(settings, scale);
  const fallbackLabel = getGradeTestScaleDefaultLabel(template.id);
  return {
    id: normalizeGradeTestScale(template.id),
    label: String(template.label || fallbackLabel || "").trim(),
    thresholds: cloneGradeTestThresholds(template.thresholds)
  };
}

function normalizeGradeTestScaleSnapshot(snapshot = null, scale = GRADE_TEST_SCALE_DEFAULT, settings = null) {
  const normalizedScale = normalizeGradeTestScale(snapshot?.id || scale);
  const fallback = buildGradeTestScaleSnapshot(settings, normalizedScale);
  const source = snapshot && typeof snapshot === "object" ? snapshot : {};
  const label = String(source.label || fallback.label || getGradeTestScaleDefaultLabel(normalizedScale) || "").trim();
  return {
    id: normalizedScale,
    label,
    thresholds: normalizeGradeTestThresholds(source.thresholds, fallback.thresholds)
  };
}


function gradeTestScaleSettingsEqual(a = null, b = null) {
  const left = normalizeGradeTestScaleSettings(a);
  const right = normalizeGradeTestScaleSettings(b);
  return JSON.stringify(left) === JSON.stringify(right);
}

function parseGradeBeValue(raw) {
  const text = String(raw ?? "").trim().replace(".", ",");
  if (!text) {
    return { valid: true, value: null };
  }
  if (!/^\d+(?:,\d)?$/.test(text)) {
    return { valid: false, value: null };
  }
  const value = Number(text.replace(",", "."));
  if (!Number.isFinite(value) || value < 0 || Math.abs(value * 2 - Math.round(value * 2)) > 0.0000001) {
    return { valid: false, value: null };
  }
  return { valid: true, value: Math.round(value * 2) / 2 };
}

function sanitizeGradeBeInput(raw, maxLength = 5) {
  const text = String(raw ?? "").replace(/[^\d.,]/g, "");
  let result = "";
  let separatorUsed = false;
  for (const char of text) {
    if (/\d/.test(char)) {
      result += char;
      continue;
    }
    if (!separatorUsed && result) {
      result += ",";
      separatorUsed = true;
    }
  }
  return result.slice(0, Math.max(1, Number(maxLength) || 5));
}

function formatGradeBeValue(value) {
  if (value === null || value === undefined || value === "") {
    return "";
  }
  const numeric = Math.max(0, Math.round((Number(value) || 0) * 2) / 2);
  if (Math.abs(numeric - Math.round(numeric)) < 0.0000001) {
    return String(Math.round(numeric));
  }
  return numeric.toFixed(1).replace(".", ",");
}

function normalizeGradeTestScores(scores = {}) {
  const source = scores && typeof scores === "object" ? scores : {};
  return Object.entries(source).reduce((result, [taskId, rawValue]) => {
    const key = String(taskId || "").trim();
    const parsed = parseGradeBeValue(rawValue);
    if (key && parsed.valid && parsed.value !== null) {
      result[key] = parsed.value;
    }
    return result;
  }, {});
}

function hasGradeTestScores(scores = {}) {
  return Object.keys(normalizeGradeTestScores(scores)).length > 0;
}

function gradeTestTaskHasMaxBe(task = null) {
  const parsed = parseGradeBeValue(task && typeof task === "object" ? task.maxBe : null);
  return parsed.valid && parsed.value !== null && Number(parsed.value || 0) > 0;
}

function isGradeTestDeficitFollowUpScore(task, scoreValue) {
  const normalizedTask = task && typeof task === "object" ? task : {};
  if (normalizedTask.deficitDiagnosisFollowUp !== true) {
    return false;
  }
  const maxBe = Number(normalizedTask.maxBe || 0);
  if (!Number.isFinite(maxBe) || maxBe <= 0) {
    return false;
  }
  const parsed = parseGradeBeValue(scoreValue);
  return parsed.valid && parsed.value !== null && Number(parsed.value) < maxBe / 3;
}

function normalizeCompetenceExpectationId(value, fallback = "") {
  const text = String(value || fallback || "")
    .replace(/[^\w-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .trim();
  return text || String(fallback || "").trim();
}

function normalizeGradeCompetenceExpectations(items = []) {
  const source = Array.isArray(items) ? items : [];
  const usedTopicIds = new Set();
  const usedCompetenceIds = new Set();
  const makeUnique = (rawId, fallback, used) => {
    const base = normalizeCompetenceExpectationId(rawId, fallback) || fallback;
    let id = base;
    let suffix = 2;
    while (used.has(id)) {
      id = `${base}-${suffix}`;
      suffix += 1;
    }
    used.add(id);
    return id;
  };
  return source.reduce((result, rawTopic, topicIndex) => {
    const item = rawTopic && typeof rawTopic === "object" ? rawTopic : {};
    const topic = String(item.topic || item.title || "").trim();
    const competenceSource = Array.isArray(item.competencies) ? item.competencies : [];
    const competencies = competenceSource.reduce((competenceResult, rawCompetence, competenceIndex) => {
      const competenceItem = rawCompetence && typeof rawCompetence === "object"
        ? rawCompetence
        : { text: rawCompetence };
      const text = String(competenceItem.text || competenceItem.label || "").trim();
      if (!text) {
        return competenceResult;
      }
      competenceResult.push({
        id: makeUnique(competenceItem.id, `k${topicIndex + 1}-${competenceIndex + 1}`, usedCompetenceIds),
        text
      });
      return competenceResult;
    }, []);
    if (!topic || !competencies.length) {
      return result;
    }
    result.push({
      id: makeUnique(item.id, `t${topicIndex + 1}`, usedTopicIds),
      topic,
      competencies
    });
    return result;
  }, []);
}

function getGradeCompetenceExpectationIds(items = []) {
  const ids = [];
  normalizeGradeCompetenceExpectations(items).forEach((topic) => {
    topic.competencies.forEach((competence) => {
      ids.push(competence.id);
    });
  });
  return ids;
}

function normalizeGradeTaskCompetenceExpectationIds(ids = [], expectations = null) {
  const source = Array.isArray(ids) ? ids : [];
  const validIds = expectations === null ? null : new Set(getGradeCompetenceExpectationIds(expectations));
  const seen = new Set();
  return source.reduce((result, rawId) => {
    const id = normalizeCompetenceExpectationId(rawId);
    if (!id || seen.has(id) || (validIds && !validIds.has(id))) {
      return result;
    }
    seen.add(id);
    result.push(id);
    return result;
  }, []);
}

function normalizeGradeTestTasks(tasks = [], options = {}) {
  const source = Array.isArray(tasks) ? tasks : [];
  const usedIds = new Set();
  const normalized = source.reduce((result, raw, index) => {
    const item = raw && typeof raw === "object" ? raw : {};
    const idBase = String(item.id || index + 1).trim() || String(index + 1);
    let id = idBase;
    let suffix = 2;
    while (usedIds.has(id)) {
      id = `${idBase}-${suffix}`;
      suffix += 1;
    }
    usedIds.add(id);
    const parsedMaxBe = parseGradeBeValue(item.maxBe);
    result.push({
      id,
      title: normalizeGradeTextPart(item.title) || `Aufgabe ${result.length + 1}`,
      maxBe: parsedMaxBe.valid && parsedMaxBe.value !== null ? parsedMaxBe.value : null,
      afb: normalizeGradeTestAfb(item.afb),
      deficitDiagnosisFollowUp: item.deficitDiagnosisFollowUp === true,
      competenceExpectationIds: normalizeGradeTaskCompetenceExpectationIds(item.competenceExpectationIds),
      customCompetenceText: String(item.customCompetenceText || "").trim(),
      sortOrder: Number(item.sortOrder || index + 1)
    });
    return result;
  }, []).sort((a, b) => Number(a.sortOrder || 0) - Number(b.sortOrder || 0));
  if (!normalized.length && options.ensureDefault !== false) {
    normalized.push({
      id: "1",
      title: "Aufgabe 1",
      maxBe: null,
      afb: "",
      deficitDiagnosisFollowUp: false,
      competenceExpectationIds: [],
      customCompetenceText: "",
      sortOrder: 1
    });
  }
  return normalized.map((task, index) => ({
    ...task,
    sortOrder: index + 1
  }));
}

function buildGradeTestAfbOptionsMarkup(selectedValue = "") {
  const selectedAfb = normalizeGradeTestAfb(selectedValue);
  return [
    `<option value=""${selectedAfb ? "" : " selected"}></option>`,
    ...GRADE_TEST_AFB_OPTIONS.map((option) => (
      `<option value="${escapeHtml(option)}"${selectedAfb === option ? " selected" : ""}>${escapeHtml(option)}</option>`
    ))
  ].join("");
}

function getNextGradeTestTaskId(tasks = []) {
  const numericMax = normalizeGradeTestTasks(tasks, { ensureDefault: false })
    .reduce((max, task) => {
      const numeric = /^\d+$/.test(String(task.id || "")) ? Number(task.id) : 0;
      return Math.max(max, numeric);
    }, 0);
  return String(numericMax + 1 || 1);
}

function calculateGradeTestRatio(tasks = [], scores = {}) {
  const normalizedTasks = normalizeGradeTestTasks(tasks, { ensureDefault: false })
    .filter((task) => Number(task.maxBe || 0) > 0);
  const normalizedScores = normalizeGradeTestScores(scores);
  const hasAnyScore = normalizedTasks.some((task) => Object.prototype.hasOwnProperty.call(normalizedScores, task.id));
  if (!normalizedTasks.length || !hasAnyScore) {
    return null;
  }
  const maxSum = normalizedTasks.reduce((sum, task) => sum + Number(task.maxBe || 0), 0);
  if (maxSum <= 0) {
    return null;
  }
  const earnedSum = normalizedTasks.reduce((sum, task) => {
    const rawScore = Object.prototype.hasOwnProperty.call(normalizedScores, task.id)
      ? Number(normalizedScores[task.id] || 0)
      : 0;
    return sum + clamp(rawScore, 0, Number(task.maxBe || 0));
  }, 0);
  const ratio = clamp(earnedSum / maxSum, 0, 1);
  return {
    earnedSum,
    maxSum,
    ratio,
    percent: Math.round(ratio * 1000) / 10
  };
}

function formatGradeTestPercentDisplay(ratioState = null) {
  const rawPercent = Number.isFinite(Number(ratioState?.ratio))
    ? Number(ratioState.ratio) * 100
    : Number(ratioState?.percent || 0);
  const percent = Math.floor(clamp(rawPercent, 0, 100));
  return `${percent}%`;
}

function formatGradeTestRatioDisplay(ratioState = null) {
  if (!ratioState || Number(ratioState.maxSum || 0) <= 0) {
    return "—";
  }
  const earned = formatGradeBeValue(ratioState.earnedSum);
  const max = formatGradeBeValue(ratioState.maxSum);
  return earned && max
    ? `${earned} / ${max} = ${formatGradeTestPercentDisplay(ratioState)}`
    : "—";
}

function calculateGradeTestMaxBeSum(tasks = []) {
  const maxSum = normalizeGradeTestTasks(tasks, { ensureDefault: false })
    .reduce((sum, task) => {
      const maxBe = Number(task.maxBe || 0);
      return maxBe > 0 ? sum + maxBe : sum;
    }, 0);
  return maxSum > 0 ? Math.round(maxSum * 2) / 2 : 0;
}

function calculateGradeTestAfbShares(tasks = [], courseLevel = "") {
  const totals = { I: 0, II: 0, III: 0 };
  const totalMaxBe = normalizeGradeTestTasks(tasks, { ensureDefault: false })
    .reduce((sum, task) => {
      const maxBe = Number(task.maxBe || 0);
      if (maxBe <= 0) {
        return sum;
      }
      const afb = normalizeGradeTestAfb(task.afb);
      if (afb === "I") {
        totals.I += maxBe;
      } else if (afb === "I/II") {
        totals.I += maxBe / 2;
        totals.II += maxBe / 2;
      } else if (afb === "II") {
        totals.II += maxBe;
      } else if (afb === "II/III") {
        totals.II += maxBe / 2;
        totals.III += maxBe / 2;
      } else if (afb === "III") {
        totals.III += maxBe;
      }
      return sum + maxBe;
    }, 0);
  const normalizedTotal = Math.round(totalMaxBe * 2) / 2;
  const baseRows = ["I", "II", "III"].map((afb) => {
    const be = Math.round(Number(totals[afb] || 0) * 2) / 2;
    const ratio = normalizedTotal > 0 ? be / normalizedTotal : 0;
    return {
      afb,
      be,
      percent: Math.round(ratio * 1000) / 10,
      hasShare: be > 0
    };
  });
  const byAfb = baseRows.reduce((result, row) => {
    result[row.afb] = row;
    return result;
  }, {});
  const courseLevelValue = String(courseLevel || "").trim().toLowerCase();
  const isLk = courseLevelValue === "lk";
  const allPositiveOk = baseRows.every((row) => row.hasShare);
  const afbIiLargestOk = byAfb.II.be > byAfb.I.be && byAfb.II.be > byAfb.III.be;
  const afbIiiOrderOk = isLk ? byAfb.III.be > byAfb.I.be : byAfb.I.be > byAfb.III.be;
  const rules = [
    {
      id: "all-positive",
      label: "Berücksichtigung aller AFB",
      ok: allPositiveOk
    },
    {
      id: "afb-ii-largest",
      label: "Schwerpunkt im AFB II",
      ok: afbIiLargestOk
    },
    {
      id: "afb-i-iii-order",
      label: isLk
        ? "Stärkere Akzentuierung von AFB III als I"
        : "Stärkere Akzentuierung von AFB I als III",
      ok: afbIiiOrderOk
    }
  ];
  const rows = baseRows.map((row) => {
    const warnings = [];
    if (!row.hasShare) {
      warnings.push("all-positive");
    }
    if (row.afb === "II" && !afbIiLargestOk) {
      warnings.push("afb-ii-largest");
    }
    if ((row.afb === "I" || row.afb === "III") && !afbIiiOrderOk) {
      warnings.push("afb-i-iii-order");
    }
    return {
      ...row,
      ok: warnings.length === 0,
      warnings
    };
  });
  return {
    totalBe: normalizedTotal,
    rows,
    rules,
    ok: rules.every((rule) => rule.ok)
  };
}

function formatGradeTestRequiredBeForThreshold(threshold, grade, maxBeSum = null) {
  const totalMaxBe = Number(maxBeSum);
  if (!Number.isFinite(totalMaxBe) || totalMaxBe <= 0) {
    return "—";
  }
  if (Number(grade) === 0) {
    return "0";
  }
  const requiredBe = Math.ceil((clamp(Number(threshold) || 0, 0, 1) * totalMaxBe * 2) - 0.0000001) / 2;
  return formatGradeBeValue(clamp(requiredBe, 0, totalMaxBe));
}

function getGradeTestScaleTooltipRows(thresholds = [], predicateSuffixes = true) {
  const normalizedThresholds = normalizeGradeTestThresholds(thresholds);
  if (normalizeGradeTestPredicateSuffixes(predicateSuffixes, true)) {
    return normalizedThresholds.map(([threshold, grade]) => ({
      threshold,
      grade,
      label: formatGradeInteger(grade)
    }));
  }
  const thresholdByGrade = new Map(
    normalizedThresholds.map(([threshold, grade]) => [Number(grade), Number(threshold) || 0])
  );
  return [
    { label: "sehr gut", grade: 13 },
    { label: "gut", grade: 10 },
    { label: "befriedigend", grade: 7 },
    { label: "ausreichend", grade: 4 },
    { label: "mangelhaft", grade: 1 },
    { label: "ungenügend", grade: 0 }
  ].map((row) => ({
    ...row,
    threshold: thresholdByGrade.has(row.grade) ? thresholdByGrade.get(row.grade) : 0
  }));
}

function buildGradeTestScaleTooltipMarkup(scaleOrTemplate = GRADE_TEST_SCALE_DEFAULT, settings = null, options = {}) {
  const template = scaleOrTemplate && typeof scaleOrTemplate === "object"
    ? normalizeGradeTestScaleSnapshot(scaleOrTemplate, scaleOrTemplate.id, settings)
    : buildGradeTestScaleSnapshot(settings, scaleOrTemplate);
  const predicateSuffixes = normalizeGradeTestPredicateSuffixes(options.predicateSuffixes, true);
  const rows = getGradeTestScaleTooltipRows(template.thresholds, predicateSuffixes);
  const showBeColumn = Boolean(options.showBeColumn);
  const maxBeSum = Object.prototype.hasOwnProperty.call(options, "maxBeSum")
    ? Number(options.maxBeSum)
    : calculateGradeTestMaxBeSum(options.testTasks);
  return `
            <div class="grade-test-scale-tooltip" role="tooltip" aria-hidden="true">
              <table>
                <thead>
                  <tr><th>Grenze</th><th>Note</th>${showBeColumn ? "<th>BE</th>" : ""}</tr>
                </thead>
                <tbody>
                  ${rows.map((row) => `
                    <tr>
                      <td>${Math.round(Number(row.threshold || 0) * 100)}%</td>
                      <td>${escapeHtml(row.label)}</td>
                      ${showBeColumn ? `<td>${formatGradeTestRequiredBeForThreshold(row.threshold, row.grade, maxBeSum)}</td>` : ""}
                    </tr>
                  `).join("")}
                </tbody>
              </table>
            </div>
          `;
}

function calculateGradeTestValue(tasks = [], scores = {}, scale = GRADE_TEST_SCALE_DEFAULT, settings = null, predicateSuffixes = true) {
  const ratioState = calculateGradeTestRatio(tasks, scores);
  if (!ratioState) {
    return null;
  }
  return calculateGradeTestValueFromRatio(ratioState, scale, settings, predicateSuffixes);
}

function calculateGradeTestValueFromRatio(ratioState = null, scale = GRADE_TEST_SCALE_DEFAULT, settings = null, predicateSuffixes = true) {
  if (!ratioState || Number(ratioState.maxSum || 0) <= 0) {
    return null;
  }
  const ratio = ratioState.ratio;
  const thresholds = scale && typeof scale === "object"
    ? normalizeGradeTestScaleSnapshot(scale, scale.id, settings).thresholds
    : buildGradeTestScaleSnapshot(settings, scale).thresholds;
  const match = thresholds.find(([threshold]) => ratio + 0.0000001 >= threshold);
  return applyGradeTestPredicateSuffixes(match ? match[1] : 0, predicateSuffixes);
}

function isGradeTestRatioInUpperThirdOfGradeBand(ratio, scale = GRADE_TEST_SCALE_DEFAULT, settings = null, predicateSuffixes = true) {
  const normalizedRatio = clamp(Number(ratio) || 0, 0, 1);
  const thresholds = scale && typeof scale === "object"
    ? normalizeGradeTestScaleSnapshot(scale, scale.id, settings).thresholds
    : buildGradeTestScaleSnapshot(settings, scale).thresholds;
  const matchIndex = thresholds.findIndex(([threshold]) => normalizedRatio + 0.0000001 >= Number(threshold || 0));
  if (matchIndex < 0) {
    return false;
  }
  let lowerBound = clamp(Number(thresholds[matchIndex]?.[0] || 0), 0, 1);
  let upperBound = matchIndex === 0
    ? 1
    : clamp(Number(thresholds[matchIndex - 1]?.[0] || 0), 0, 1);
  if (!normalizeGradeTestPredicateSuffixes(predicateSuffixes, true)) {
    const groupedRows = getGradeTestScaleTooltipRows(thresholds, false);
    const currentGrade = Number(thresholds[matchIndex]?.[1]);
    const groupIndex = groupedRows.findIndex((row) => Number(row.grade) <= currentGrade);
    if (groupIndex >= 0) {
      lowerBound = clamp(Number(groupedRows[groupIndex]?.threshold || 0), 0, 1);
      upperBound = groupIndex === 0
        ? 1
        : clamp(Number(groupedRows[groupIndex - 1]?.threshold || 0), 0, 1);
    }
  }
  const bandWidth = upperBound - lowerBound;
  if (bandWidth <= 0.0000001) {
    return false;
  }
  return normalizedRatio + 0.0000001 >= lowerBound + ((bandWidth * 2) / 3);
}

function formatGradeBeAverageValue(value) {
  if (value === null || value === undefined || value === "") {
    return "";
  }
  const numeric = Math.max(0, Math.round((Number(value) || 0) * 10) / 10);
  if (Math.abs(numeric - Math.round(numeric)) < 0.0000001) {
    return String(Math.round(numeric));
  }
  return numeric.toFixed(1).replace(".", ",");
}

function formatGradeTestAverageRatioDisplay(ratioState = null) {
  if (!ratioState || Number(ratioState.maxSum || 0) <= 0) {
    return "—";
  }
  const earned = formatGradeBeAverageValue(ratioState.earnedSum);
  const max = formatGradeBeValue(ratioState.maxSum);
  return earned && max
    ? `${earned} / ${max} = ${formatGradeTestPercentDisplay(ratioState)}`
    : "—";
}

function getGradeTestAverageTaskColorClasses(tasks = [], taskAverages = {}) {
  const normalizedTasks = normalizeGradeTestTasks(tasks, { ensureDefault: false });
  const classes = normalizedTasks.reduce((result, task) => {
    result[task.id] = "";
    return result;
  }, {});
  const ranked = normalizedTasks
    .map((task) => {
      const average = taskAverages[task.id];
      const maxBe = Number(task.maxBe || 0);
      if (average === null || average === undefined || maxBe <= 0) {
        return null;
      }
      return {
        taskId: task.id,
        ratio: clamp(Number(average || 0) / maxBe, 0, 1)
      };
    })
    .filter(Boolean)
    .sort((left, right) => left.ratio - right.ratio);
  if (!ranked.length) {
    return classes;
  }
  const minRatio = ranked[0].ratio;
  const maxRatio = ranked[ranked.length - 1].ratio;
  if (Math.abs(maxRatio - minRatio) < 0.0000001) {
    ranked.forEach((item) => {
      classes[item.taskId] = "is-mid";
    });
    return classes;
  }
  if (ranked.length === 1) {
    classes[ranked[0].taskId] = "is-mid";
    return classes;
  }
  if (ranked.length === 2) {
    classes[ranked[0].taskId] = "is-low";
    classes[ranked[1].taskId] = "is-high";
    return classes;
  }
  const thirdSize = Math.max(1, Math.floor(ranked.length / 3));
  ranked.forEach((item, index) => {
    if (index < thirdSize) {
      classes[item.taskId] = "is-low";
    } else if (index >= ranked.length - thirdSize) {
      classes[item.taskId] = "is-high";
    } else {
      classes[item.taskId] = "is-mid";
    }
  });
  return classes;
}

function calculateGradeTestAverageState(tasks = [], scoreEntries = [], scale = GRADE_TEST_SCALE_DEFAULT, settings = null, deficitThreshold = GRADE_DEFICIT_THRESHOLD_DEFAULT, predicateSuffixes = true) {
  const normalizedTasks = normalizeGradeTestTasks(tasks, { ensureDefault: false });
  const normalizedScoresList = (Array.isArray(scoreEntries) ? scoreEntries : [])
    .map((scores) => normalizeGradeTestScores(scores))
    .filter((scores) => Object.keys(scores).length > 0);
  const taskAverages = normalizedTasks.reduce((result, task) => {
    const values = normalizedScoresList
      .filter((scores) => Object.prototype.hasOwnProperty.call(scores, task.id))
      .map((scores) => Number(scores[task.id] || 0));
    result[task.id] = values.length
      ? values.reduce((sum, value) => sum + value, 0) / values.length
      : null;
    return result;
  }, {});
  const ratioTasks = normalizedTasks.filter((task) => (
    Number(task.maxBe || 0) > 0
    && taskAverages[task.id] !== null
    && taskAverages[task.id] !== undefined
  ));
  const maxSum = ratioTasks.reduce((sum, task) => sum + Number(task.maxBe || 0), 0);
  if (maxSum <= 0) {
    return {
      taskAverages,
      taskAverageClasses: getGradeTestAverageTaskColorClasses(normalizedTasks, taskAverages),
      ratioState: null,
      gradeValue: null,
      deficitShare: null
    };
  }
  const earnedSum = ratioTasks.reduce((sum, task) => {
    const average = taskAverages[task.id];
    if (average === null || average === undefined) {
      return sum;
    }
    return sum + clamp(Number(average || 0), 0, Number(task.maxBe || 0));
  }, 0);
  const ratio = clamp(earnedSum / maxSum, 0, 1);
  const ratioState = {
    earnedSum,
    maxSum,
    ratio,
    percent: Math.round(ratio * 1000) / 10
  };
  return {
    taskAverages,
    taskAverageClasses: getGradeTestAverageTaskColorClasses(normalizedTasks, taskAverages),
    ratioState,
    gradeValue: calculateGradeTestValueFromRatio(ratioState, scale, settings, predicateSuffixes),
    deficitShare: calculateGradeDeficitShare(
      normalizedScoresList.map((scores) => calculateGradeTestValue(normalizedTasks, scores, scale, settings, predicateSuffixes)),
      deficitThreshold
    )
  };
}

function normalizeGradeEntryChecked(value) {
  if (value === true || value === 1) {
    return true;
  }
  const text = String(value || "").trim().toLowerCase();
  return text === "true" || text === "1" || text === "yes" || text === "on";
}

function normalizeGradeDraftEntry(value) {
  if (value && typeof value === "object") {
    const parsedValue = parseGradeValue(value.value, 15);
    return {
      value: parsedValue.valid ? parsedValue.value : null,
      checked: normalizeGradeEntryChecked(value.checked) ? true : null,
      testScores: normalizeGradeTestScores(value.testScores)
    };
  }
  if (typeof value === "boolean") {
    return {
      value: null,
      checked: value ? true : null,
      testScores: {}
    };
  }
  const parsedValue = parseGradeValue(value, 15);
  return {
    value: parsedValue.valid ? parsedValue.value : null,
    checked: null,
    testScores: {}
  };
}

function normalizeGradeOverrideScope(scope) {
  const value = String(scope || "").trim().toLowerCase();
  return value === "course" || value === "category" || value === "subcategory" ? value : "";
}

function normalizeGradePeriod(period) {
  const value = String(period || "").trim().toLowerCase();
  return value === "h1" || value === "h2" || value === "year" ? value : "year";
}

function normalizeGradeDisplaySystem(value) {
  return String(value || "").trim().toLowerCase() === GRADE_DISPLAY_SYSTEM_SCHOOL
    ? GRADE_DISPLAY_SYSTEM_SCHOOL
    : GRADE_DISPLAY_SYSTEM_DEFAULT;
}

function normalizeGradeTestAfb(value) {
  const text = String(value || "").trim().toUpperCase();
  return GRADE_TEST_AFB_OPTIONS.includes(text) ? text : "";
}

function normalizeLessonTimeValue(value) {
  const text = String(value || "").trim();
  if (!text) {
    return "";
  }
  const match = text.match(/^(\d{2}):(\d{2})$/);
  if (!match) {
    return "";
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (!Number.isInteger(hours) || !Number.isInteger(minutes) || hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
    return "";
  }
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
}

function parseLessonTimeMinutes(value) {
  const normalized = normalizeLessonTimeValue(value);
  if (!normalized) {
    return null;
  }
  const [hours, minutes] = normalized.split(":").map(Number);
  return hours * 60 + minutes;
}


function normalizeLessonTimes(value, hoursPerDay = HOURS_PER_DAY_DEFAULT) {
  const count = clamp(Number(hoursPerDay) || HOURS_PER_DAY_DEFAULT, 1, 12);
  const entries = Array.isArray(value) ? value : [];
  const byLesson = new Map();
  entries.forEach((entry) => {
    const rawLesson = Number(entry && entry.lesson);
    if (!Number.isInteger(rawLesson) || rawLesson < 1 || rawLesson > count) {
      return;
    }
    const lesson = rawLesson;
    byLesson.set(lesson, {
      lesson,
      start: normalizeLessonTimeValue(entry && entry.start),
      end: normalizeLessonTimeValue(entry && entry.end)
    });
  });
  return Array.from({ length: count }, (_, index) => {
    const lesson = index + 1;
    return byLesson.get(lesson) || { lesson, start: "", end: "" };
  });
}


function validateLessonTimes(lessonTimes, hoursPerDay = HOURS_PER_DAY_DEFAULT) {
  const normalized = normalizeLessonTimes(lessonTimes, hoursPerDay);
  const hasAnyValue = normalized.some((entry) => Boolean(entry.start || entry.end));
  if (!hasAnyValue) {
    return { valid: true, normalized, hasAnyValue: false, message: "" };
  }
  let previousEnd = null;
  for (const entry of normalized) {
    if (!entry.start || !entry.end) {
      return {
        valid: false,
        normalized,
        hasAnyValue: true,
        message: `Bitte für die ${entry.lesson}. Stunde Start und Ende angeben.`
      };
    }
    const startMinutes = parseLessonTimeMinutes(entry.start);
    const endMinutes = parseLessonTimeMinutes(entry.end);
    if (startMinutes === null || endMinutes === null) {
      return {
        valid: false,
        normalized,
        hasAnyValue: true,
        message: `Die Uhrzeiten der ${entry.lesson}. Stunde sind ungültig.`
      };
    }
    if (startMinutes >= endMinutes) {
      return {
        valid: false,
        normalized,
        hasAnyValue: true,
        message: `Die ${entry.lesson}. Stunde muss vor ihrem Ende beginnen.`
      };
    }
    if (previousEnd !== null && startMinutes < previousEnd) {
      return {
        valid: false,
        normalized,
        hasAnyValue: true,
        message: "Die Stundenzeiten dürfen sich nicht überschneiden und müssen aufsteigend sein."
      };
    }
    previousEnd = endMinutes;
  }
  return { valid: true, normalized, hasAnyValue: true, message: "" };
}

function getGradePeriodLabel(period) {
  const normalized = normalizeGradePeriod(period);
  return normalized === "h1" ? "HJ1" : normalized === "h2" ? "HJ2" : "Jahr";
}

function parsePedagogicalGradeValue(raw, maxValue = 15) {
  const text = String(raw ?? "").trim();
  if (!text) {
    return { valid: true, value: null };
  }
  if (!/^\d+(?:[.,]\d{1})?$/.test(text)) {
    return { valid: false, value: null };
  }
  const value = Number(text.replace(",", "."));
  const normalizedMax = Number.isFinite(maxValue) ? Math.max(0, Number(maxValue) || 0) : Number.POSITIVE_INFINITY;
  if (!Number.isFinite(value) || value < 0 || value > normalizedMax) {
    return { valid: false, value: null };
  }
  return { valid: true, value: Math.round(value * 10) / 10 };
}

function formatPedagogicalGradeInput(value) {
  if (value === null || value === undefined || value === "") {
    return "";
  }
  const numeric = clamp(Number(value) || 0, 0, 15);
  if (Math.abs(numeric - Math.round(numeric)) < 0.0000001) {
    return String(Math.round(numeric));
  }
  return numeric.toFixed(1).replace(".", ",");
}

function sanitizePedagogicalGradeInput(raw, maxLength = 4) {
  const text = String(raw ?? "").replace(/[^\d.,]/g, "");
  let result = "";
  let separatorUsed = false;
  let decimalDigits = 0;
  for (const char of text) {
    if (/\d/.test(char)) {
      if (!separatorUsed) {
        result += char;
        continue;
      }
      if (decimalDigits < 1) {
        result += char;
        decimalDigits += 1;
      }
      continue;
    }
    if (!separatorUsed && result) {
      result += ",";
      separatorUsed = true;
    }
  }
  return result.slice(0, Math.max(1, Number(maxLength) || 4));
}

function parseGradeValue(raw, maxValue = Number.POSITIVE_INFINITY) {
  const text = String(raw ?? "").trim();
  if (!text) {
    return { valid: true, value: null };
  }
  if (!/^\d+$/.test(text)) {
    return { valid: false, value: null };
  }
  const value = Number(text);
  const normalizedMax = Number.isFinite(maxValue) ? Math.max(0, Math.round(Number(maxValue) || 0)) : Number.POSITIVE_INFINITY;
  if (!Number.isInteger(value) || value < 0 || value > normalizedMax) {
    return { valid: false, value: null };
  }
  return { valid: true, value };
}

function formatGradeInteger(value, maxValue = 15) {
  const normalizedMax = Number.isFinite(maxValue) ? Math.max(0, Math.round(Number(maxValue) || 0)) : 99;
  const numeric = clamp(Math.round(Number(value) || 0), 0, normalizedMax);
  const minWidth = Math.max(2, String(normalizedMax).length);
  return String(numeric).padStart(minWidth, "0");
}


function getRoundedGradeDisplayValue(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }
  return clamp(Math.round(Number(value) || 0), 0, 15);
}

function formatGradeDisplayForSystem(value, displaySystem = GRADE_DISPLAY_SYSTEM_DEFAULT, options = {}) {
  const rounded = getRoundedGradeDisplayValue(value);
  if (rounded === null) {
    return "—";
  }
  if (normalizeGradeDisplaySystem(displaySystem) === GRADE_DISPLAY_SYSTEM_SCHOOL) {
    const label = GRADE_DISPLAY_SYSTEM_SCHOOL_LABELS[rounded] || "—";
    return options.predicateSuffixes === false ? label.replace(/[+-]$/, "") : label;
  }
  return formatGradeInteger(rounded);
}

function formatGradeInputForSystem(value, displaySystem = GRADE_DISPLAY_SYSTEM_DEFAULT, options = {}) {
  if (value === null || value === undefined || value === "") {
    return "";
  }
  if (normalizeGradeDisplaySystem(displaySystem) === GRADE_DISPLAY_SYSTEM_SCHOOL) {
    return GRADE_DISPLAY_SYSTEM_SCHOOL_LABELS[getRoundedGradeDisplayValue(value)] || "";
  }
  if (!options.pedagogical) {
    return formatGradeInteger(value);
  }
  const formatted = formatPedagogicalGradeInput(value);
  const [integerPart, decimalPart] = formatted.split(",");
  return decimalPart === undefined
    ? integerPart.padStart(2, "0")
    : `${integerPart.padStart(2, "0")},${decimalPart}`;
}

function normalizeSchoolGradeInput(raw) {
  return String(raw ?? "")
    .trim()
    .replace(/[\u2010-\u2015\u2212]/g, "-");
}

function parseSchoolGradeValue(raw) {
  const text = normalizeSchoolGradeInput(raw);
  if (!text) {
    return { valid: true, value: null };
  }
  if (!/^[1-6][+-]?$/.test(text)) {
    return { valid: false, value: null };
  }
  const value = GRADE_DISPLAY_SYSTEM_SCHOOL_LABELS.indexOf(text);
  return value >= 0
    ? { valid: true, value }
    : { valid: false, value: null };
}

function parseGradeInputForSystem(raw, displaySystem = GRADE_DISPLAY_SYSTEM_DEFAULT, options = {}) {
  if (normalizeGradeDisplaySystem(displaySystem) === GRADE_DISPLAY_SYSTEM_SCHOOL) {
    return parseSchoolGradeValue(raw);
  }
  const text = String(raw ?? "").trim();
  if (!text) {
    return { valid: true, value: null };
  }
  if (options.pedagogical) {
    return /^\d{2}(?:[.,]\d)?$/.test(text)
      ? parsePedagogicalGradeValue(text, 15)
      : { valid: false, value: null };
  }
  return /^\d{2}$/.test(text)
    ? parseGradeValue(text, 15)
    : { valid: false, value: null };
}

function normalizeGradeDeficitThreshold(value, fallback = GRADE_DEFICIT_THRESHOLD_DEFAULT) {
  const parsed = parseGradeValue(value, 15);
  if (parsed.valid && parsed.value !== null) {
    return parsed.value;
  }
  const fallbackParsed = parseGradeValue(fallback, 15);
  return fallbackParsed.valid && fallbackParsed.value !== null ? fallbackParsed.value : GRADE_DEFICIT_THRESHOLD_DEFAULT;
}

function isGradeValueBelowThreshold(value, threshold = GRADE_DEFICIT_THRESHOLD_DEFAULT) {
  if (value === null || value === undefined || value === "") {
    return false;
  }
  const numeric = Number(value);
  const normalizedThreshold = normalizeGradeDeficitThreshold(threshold, GRADE_DEFICIT_THRESHOLD_DEFAULT);
  return Number.isFinite(numeric) && numeric <= normalizedThreshold;
}

function calculateGradeDeficitShare(values = [], threshold = GRADE_DEFICIT_THRESHOLD_DEFAULT) {
  const normalizedValues = (Array.isArray(values) ? values : [])
    .map((value) => {
      if (value === null || value === undefined || value === "") {
        return null;
      }
      const numeric = Number(value);
      return Number.isFinite(numeric) ? numeric : null;
    })
    .filter((value) => value !== null && value !== undefined);
  if (!normalizedValues.length) {
    return null;
  }
  const deficitCount = normalizedValues.filter((value) => isGradeValueBelowThreshold(value, threshold)).length;
  return Math.round((deficitCount / normalizedValues.length) * 100);
}

function formatGradeDeficitShare(value) {
  return value === null || value === undefined ? "—" : `${Math.round(Number(value) || 0)}%`;
}

function calculateGradeEntryAverage(values = []) {
  const normalizedValues = (Array.isArray(values) ? values : [])
    .map((value) => {
      const parsed = parseGradeValue(value, 15);
      return parsed.valid ? parsed.value : null;
    })
    .filter((value) => value !== null && value !== undefined);
  if (!normalizedValues.length) {
    return null;
  }
  return normalizedValues.reduce((sum, value) => sum + Number(value || 0), 0) / normalizedValues.length;
}

function formatGradeTooltipDecimal(value) {
  if (value === null || value === undefined || value === "") {
    return "—";
  }
  const numeric = clamp(Number(value) || 0, 0, 15);
  return numeric.toFixed(1).replace(".", ",");
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function normalizeGradeStudentPortrait(value) {
  if (!value || typeof value !== "object" || value.mime !== GRADE_STUDENT_PORTRAIT_MIME) return null;
  const data = typeof value.data === "string" ? value.data.trim() : "";
  if (!data || data.length > Math.ceil(GRADE_STUDENT_PORTRAIT_MAX_BYTES * 4 / 3) + 8) return null;
  if (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(data)) return null;
  return { mime: GRADE_STUDENT_PORTRAIT_MIME, data };
}

function base64ToGradeStudentPortraitBytes(data) {
  const binary = window.atob(data);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

function bytesToBase64(bytes) {
  let binary = "";
  const chunkSize = 0x8000;
  for (let offset = 0; offset < bytes.length; offset += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + chunkSize));
  }
  return window.btoa(binary);
}

function canvasToWebpBlob(canvas, quality) {
  return new Promise((resolve) => canvas.toBlob(resolve, GRADE_STUDENT_PORTRAIT_MIME, quality));
}

async function encodeGradeStudentPortraitCrop(image, sourceX, sourceY, sourceSize) {
  const canvas = document.createElement("canvas");
  canvas.width = GRADE_STUDENT_PORTRAIT_SIZE;
  canvas.height = GRADE_STUDENT_PORTRAIT_SIZE;
  const context = canvas.getContext("2d", { alpha: false });
  if (!context) throw new Error("Die Bildverarbeitung wird von diesem Browser nicht unterstützt.");
  context.drawImage(image, sourceX, sourceY, sourceSize, sourceSize, 0, 0, canvas.width, canvas.height);
  for (let quality = 0.86; quality >= 0.38; quality -= 0.08) {
    const blob = await canvasToWebpBlob(canvas, quality);
    if (blob && blob.size <= GRADE_STUDENT_PORTRAIT_MAX_BYTES) {
      return { mime: GRADE_STUDENT_PORTRAIT_MIME, data: bytesToBase64(new Uint8Array(await blob.arrayBuffer())) };
    }
  }
  throw new Error("Das Bild lässt sich nicht auf höchstens 150 KB komprimieren.");
}

async function prepareGradeStudentPortrait(file) {
  if (!(file instanceof File) || !GRADE_STUDENT_PORTRAIT_INPUT_TYPES.has(file.type)) {
    throw new Error("Bitte ein JPEG-, PNG- oder WebP-Bild auswählen.");
  }
  const sourceUrl = URL.createObjectURL(file);
  try {
    const image = new Image();
    image.src = sourceUrl;
    await image.decode();
    if (!image.naturalWidth || !image.naturalHeight) throw new Error("Das Bild konnte nicht gelesen werden.");
    const sourceSize = Math.min(image.naturalWidth, image.naturalHeight);
    const sourceX = Math.floor((image.naturalWidth - sourceSize) / 2);
    const sourceY = Math.floor((image.naturalHeight - sourceSize) / 2);
    return encodeGradeStudentPortraitCrop(image, sourceX, sourceY, sourceSize);
  } catch (error) {
    throw error instanceof Error ? error : new Error("Das Bild konnte nicht verarbeitet werden.");
  } finally {
    URL.revokeObjectURL(sourceUrl);
  }
}


function buildGradeStudentPerformanceFlairBadgeMarkup(student) {
  const performanceFlair = normalizeGradePerformanceFlair(student && student.performanceFlair);
  if (!performanceFlair) {
    return "";
  }
  return `<span class="grades-student-flair" aria-label="Flair ${escapeHtml(performanceFlair)}">${escapeHtml(performanceFlair)}</span>`;
}

function buildGradeStudentNameInnerMarkup(student, studentName) {
  return `${escapeHtml(studentName)}${buildGradeStudentPerformanceFlairBadgeMarkup(student)}`;
}

function createGradeStudentNameElement(student, studentName, options = {}) {
  const node = document.createElement("div");
  node.className = `grades-student-name${options.active ? " is-active" : ""}${options.placeholder ? " is-placeholder" : ""}`;
  if (!options.placeholder) {
    const studentId = Number(student?.id) || 0;
    if (studentId > 0) {
      node.dataset.gradeStudentName = String(studentId);
    }
    node.dataset.studentLabel = String(studentName || "");
    node.append(document.createTextNode(String(studentName || "")));
    if (options.portraitUrl) {
      const portrait = document.createElement("img");
      portrait.className = "grade-student-portrait grade-student-portrait--entry";
      portrait.src = options.portraitUrl;
      portrait.alt = "";
      portrait.dataset.gradeStudentPortraitPreview = "1";
      portrait.setAttribute("role", "button");
      portrait.tabIndex = 0;
      portrait.setAttribute("aria-label", "Foto vergrößern");
      portrait.title = "Foto vergrößern";
      portrait.decoding = "async";
      node.prepend(portrait);
    } else if (options.showPortraitPlaceholder) {
      const portraitPlaceholder = document.createElement("span");
      portraitPlaceholder.className = "grade-student-portrait-placeholder grade-student-portrait-placeholder--entry";
      portraitPlaceholder.setAttribute("aria-hidden", "true");
      portraitPlaceholder.textContent = "👤︎";
      node.prepend(portraitPlaceholder);
    }
    const performanceFlair = normalizeGradePerformanceFlair(student?.performanceFlair);
    if (performanceFlair) {
      const flair = document.createElement("span");
      flair.className = "grades-student-flair";
      flair.setAttribute("aria-label", `Flair ${performanceFlair}`);
      flair.textContent = performanceFlair;
      node.append(flair);
    }
  } else {
    node.textContent = "\u00a0";
  }
  return node;
}

function buildGradePeriodKey(courseId, period = "year") {
  return `${Number(courseId) || 0}:${normalizeGradePeriod(period)}`;
}

function buildGradeCategoryKey(courseId, categoryId, period = "year") {
  return `${Number(courseId) || 0}:${normalizeGradePeriod(period)}:${Number(categoryId) || 0}`;
}

function buildGradeSubcategoryKey(courseId, categoryId, subcategoryId, period = "year") {
  return `${Number(courseId) || 0}:${normalizeGradePeriod(period)}:${Number(categoryId) || 0}:${Number(subcategoryId) || 0}`;
}

function normalizeGradeStructureWeight(value, fallback = 1) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < 0) {
    const fallbackNumber = Number(fallback);
    return Number.isFinite(fallbackNumber) && fallbackNumber >= 0 ? fallbackNumber : 1;
  }
  return parsed;
}

function normalizeGradeStructureWeights(weights = null, fallback = 1) {
  const source = weights && typeof weights === "object" ? weights : {};
  const fallbackWeight = normalizeGradeStructureWeight(fallback, 1);
  return {
    h1: normalizeGradeStructureWeight(source.h1, fallbackWeight),
    h2: normalizeGradeStructureWeight(source.h2, fallbackWeight)
  };
}

function getGradeStructurePeriodWeight(item = null, period = "h1") {
  const normalizedPeriod = normalizeGradeHalfYear(period);
  const fallback = normalizeGradeStructureWeight(item && item.weight, 1);
  const weights = normalizeGradeStructureWeights(item && item.weights, fallback);
  return weights[normalizedPeriod];
}


function normalizeGradeStructureDraft(categories) {
  if (!Array.isArray(categories)) {
    return [];
  }
  return categories.map((category) => {
    const fallbackWeight = normalizeGradeStructureWeight(category && category.weight, 1);
    const weights = normalizeGradeStructureWeights(category && category.weights, fallbackWeight);
    return {
      id: Number(category && category.id) || 0,
      name: normalizeGradeTextPart(category && category.name),
      weight: weights.h1,
      weights,
      subcategories: Array.isArray(category && category.subcategories)
        ? category.subcategories.map((subcategory) => {
          const subcategoryFallbackWeight = normalizeGradeStructureWeight(subcategory && subcategory.weight, 1);
          const subcategoryWeights = normalizeGradeStructureWeights(subcategory && subcategory.weights, subcategoryFallbackWeight);
          return {
            id: Number(subcategory && subcategory.id) || 0,
            name: normalizeGradeTextPart(subcategory && subcategory.name),
            weight: subcategoryWeights.h1,
            weights: subcategoryWeights,
          };
        })
        : [],
    };
  });
}

function normalizeGradeStructurePeriodDraft(categories) {
  if (!Array.isArray(categories)) {
    return [];
  }
  return categories.map((category) => ({
    id: Number(category && category.id) || 0,
    name: normalizeGradeTextPart(category && category.name),
    weight: normalizeGradeStructureWeight(category && category.weight, 1),
    subcategories: Array.isArray(category && category.subcategories)
      ? category.subcategories.map((subcategory) => ({
        id: Number(subcategory && subcategory.id) || 0,
        name: normalizeGradeTextPart(subcategory && subcategory.name),
        weight: normalizeGradeStructureWeight(subcategory && subcategory.weight, 1),
      }))
      : [],
  }));
}

function normalizeGradeStructurePeriodCategories(source = null) {
  const record = source && typeof source === "object" && !Array.isArray(source) ? source : {};
  const legacyCategories = Array.isArray(source)
    ? source
    : (Array.isArray(record.categories) ? record.categories : []);
  const periodCategories = record.periodCategories && typeof record.periodCategories === "object"
    ? record.periodCategories
    : {};
  return {
    h1: Array.isArray(periodCategories.h1)
      ? normalizeGradeStructurePeriodDraft(periodCategories.h1)
      : normalizeGradeStructurePeriodDraft(buildGradeStructureForPeriod(legacyCategories, "h1")),
    h2: Array.isArray(periodCategories.h2)
      ? normalizeGradeStructurePeriodDraft(periodCategories.h2)
      : normalizeGradeStructurePeriodDraft(buildGradeStructureForPeriod(legacyCategories, "h2"))
  };
}

function createEmptyGradeStructureWeightOverridePeriod() {
  return { categories: {}, subcategories: {} };
}

function normalizeGradeStructureWeightOverridePeriod(rawPeriod = null) {
  const source = rawPeriod && typeof rawPeriod === "object" ? rawPeriod : {};
  const normalizeMap = (rawMap) => {
    const result = {};
    if (!rawMap || typeof rawMap !== "object") {
      return result;
    }
    Object.entries(rawMap).forEach(([key, value]) => {
      const normalizedKey = String(key || "").trim();
      if (!normalizedKey) {
        return;
      }
      const parsedValue = Number(value);
      if (!Number.isFinite(parsedValue) || parsedValue < 0) {
        return;
      }
      const normalizedValue = normalizeGradeStructureWeight(parsedValue, 0);
      result[normalizedKey] = normalizedValue;
    });
    return result;
  };
  return {
    categories: normalizeMap(source.categories),
    subcategories: normalizeMap(source.subcategories)
  };
}

function normalizeGradeStructurePerformanceFlairWeightOverrides(rawOverrides = null) {
  const source = rawOverrides && typeof rawOverrides === "object" ? rawOverrides : {};
  const result = {};
  GRADE_STUDENT_PERFORMANCE_FLAIRS.forEach((flair) => {
    const flairSource = source[flair] && typeof source[flair] === "object" ? source[flair] : {};
    const normalizedFlair = {};
    ["h1", "h2"].forEach((period) => {
      const normalizedPeriod = normalizeGradeStructureWeightOverridePeriod(flairSource[period]);
      if (Object.keys(normalizedPeriod.categories).length > 0 || Object.keys(normalizedPeriod.subcategories).length > 0) {
        normalizedFlair[period] = normalizedPeriod;
      }
    });
    if (Object.keys(normalizedFlair).length > 0) {
      result[flair] = normalizedFlair;
    }
  });
  return result;
}

function materializeGradeStructurePerformanceFlairWeightOverrides(periodCategories, rawOverrides = null) {
  const normalizedByPeriod = normalizeGradeStructurePeriodCategories({ periodCategories });
  const result = normalizeGradeStructurePerformanceFlairWeightOverrides(rawOverrides);
  GRADE_STUDENT_PERFORMANCE_FLAIRS.forEach((flair) => {
    if (!result[flair]) {
      result[flair] = {};
    }
    ["h1", "h2"].forEach((period) => {
      const categories = normalizedByPeriod[period] || [];
      const periodOverrides = normalizeGradeStructureWeightOverridePeriod(result[flair][period]);
      categories.forEach((category, categoryIndex) => {
        const categoryKey = getGradeStructureOverrideKeyForCategory(category, categoryIndex);
        if (!Object.prototype.hasOwnProperty.call(periodOverrides.categories, categoryKey)) {
          periodOverrides.categories[categoryKey] = normalizeGradeStructureWeight(category.weight, 1);
        }
        (category.subcategories || []).forEach((subcategory, subcategoryIndex) => {
          const subcategoryKey = getGradeStructureOverrideKeyForSubcategory(subcategory, categoryIndex, subcategoryIndex);
          if (!Object.prototype.hasOwnProperty.call(periodOverrides.subcategories, subcategoryKey)) {
            periodOverrides.subcategories[subcategoryKey] = normalizeGradeStructureWeight(subcategory.weight, 1);
          }
        });
      });
      result[flair][period] = periodOverrides;
    });
  });
  return normalizeGradeStructurePerformanceFlairWeightOverrides(result);
}

function getGradeStructureOverrideKeyForCategory(category, categoryIndex) {
  const id = Number(category && category.id) || 0;
  return id > 0 ? String(id) : `index:${Number(categoryIndex) || 0}`;
}

function getGradeStructureOverrideKeyForSubcategory(subcategory, categoryIndex, subcategoryIndex) {
  const id = Number(subcategory && subcategory.id) || 0;
  return id > 0 ? String(id) : `index:${Number(categoryIndex) || 0}:${Number(subcategoryIndex) || 0}`;
}

function getGradeStructureWeightOverrideValue(overrides, flair, period, scope, key) {
  const normalizedFlair = normalizeGradePerformanceFlair(flair);
  const normalizedPeriod = normalizeGradeHalfYear(period);
  if (!normalizedFlair || !key) {
    return null;
  }
  const periodOverrides = overrides?.[normalizedFlair]?.[normalizedPeriod];
  const map = scope === "subcategory" ? periodOverrides?.subcategories : periodOverrides?.categories;
  if (!map || !Object.prototype.hasOwnProperty.call(map, key)) {
    return null;
  }
  const parsedValue = Number(map[key]);
  return Number.isFinite(parsedValue) && parsedValue >= 0
    ? normalizeGradeStructureWeight(parsedValue, 0)
    : null;
}

function setGradeStructureWeightOverride(overrides, flair, period, scope, key, value) {
  const normalizedFlair = normalizeGradePerformanceFlair(flair);
  const normalizedPeriod = normalizeGradeHalfYear(period);
  if (!normalizedFlair || !key) {
    return normalizeGradeStructurePerformanceFlairWeightOverrides(overrides);
  }
  const next = cloneJsonValue(overrides && typeof overrides === "object" ? overrides : {}, {});
  const normalizedValue = normalizeGradeStructureWeight(value, 0);
  const periodOverrides = next[normalizedFlair]?.[normalizedPeriod] || createEmptyGradeStructureWeightOverridePeriod();
  const targetMap = scope === "subcategory" ? periodOverrides.subcategories : periodOverrides.categories;
  targetMap[key] = normalizedValue;
  next[normalizedFlair] = {
    ...(next[normalizedFlair] || {}),
    [normalizedPeriod]: periodOverrides
  };
  return normalizeGradeStructurePerformanceFlairWeightOverrides(next);
}

function applyGradeStructurePerformanceFlairWeightOverrides(categories, overrides, flair, period) {
  const normalizedFlair = normalizeGradePerformanceFlair(flair);
  const normalizedPeriod = normalizeGradeHalfYear(period);
  const sourceCategories = normalizeGradeStructurePeriodDraft(categories);
  if (!normalizedFlair) {
    return sourceCategories;
  }
  return sourceCategories.map((category, categoryIndex) => {
    const categoryKey = getGradeStructureOverrideKeyForCategory(category, categoryIndex);
    const categoryOverride = getGradeStructureWeightOverrideValue(
      overrides,
      normalizedFlair,
      normalizedPeriod,
      "category",
      categoryKey
    );
    return {
      ...category,
      weight: categoryOverride === null ? category.weight : categoryOverride,
      subcategories: (category.subcategories || []).map((subcategory, subcategoryIndex) => {
        const subcategoryKey = getGradeStructureOverrideKeyForSubcategory(subcategory, categoryIndex, subcategoryIndex);
        const subcategoryOverride = getGradeStructureWeightOverrideValue(
          overrides,
          normalizedFlair,
          normalizedPeriod,
          "subcategory",
          subcategoryKey
        );
        return {
          ...subcategory,
          weight: subcategoryOverride === null ? subcategory.weight : subcategoryOverride
        };
      })
    };
  });
}

function normalizePercentWeights(items) {
  const normalizedItems = Array.isArray(items) ? items : [];
  const total = normalizedItems.reduce((sum, item) => sum + Math.max(0, Number(item && item.weight) || 0), 0);
  if (normalizedItems.length === 0) {
    return [];
  }
  if (total <= 0) {
    const equalWeight = Number((100 / normalizedItems.length).toFixed(2));
    return normalizedItems.map((item, index) => ({
      ...item,
      weight: index === normalizedItems.length - 1
        ? Number((100 - equalWeight * (normalizedItems.length - 1)).toFixed(2))
        : equalWeight,
    }));
  }
  if (Math.abs(total - 100) < 0.0001) {
    return normalizedItems.map((item) => ({ ...item, weight: Number(item.weight) || 0 }));
  }
  let consumed = 0;
  return normalizedItems.map((item, index) => {
    if (index === normalizedItems.length - 1) {
      return {
        ...item,
        weight: Number((100 - consumed).toFixed(2)),
      };
    }
    const percent = Number((((Math.max(0, Number(item && item.weight) || 0) / total) * 100)).toFixed(2));
    consumed += percent;
    return {
      ...item,
      weight: percent,
    };
  });
}


function normalizeGradeStructurePeriodPercentDraft(categories) {
  const normalizedCategories = normalizePercentWeights(normalizeGradeStructurePeriodDraft(categories));
  return normalizedCategories.map((category) => ({
    ...category,
    subcategories: normalizePercentWeights(category.subcategories || [])
  }));
}

function normalizeGradeStructurePeriodCategoriesPercentDraft(source = null) {
  const periodCategories = normalizeGradeStructurePeriodCategories(source);
  return {
    h1: normalizeGradeStructurePeriodPercentDraft(periodCategories.h1),
    h2: normalizeGradeStructurePeriodPercentDraft(periodCategories.h2)
  };
}

function buildGradeStructureForPeriod(categories, period = "h1") {
  const normalizedPeriod = normalizeGradeHalfYear(period);
  return normalizeGradeStructureDraft(categories).map((category) => ({
    ...category,
    weight: getGradeStructurePeriodWeight(category, normalizedPeriod),
    subcategories: (category.subcategories || []).map((subcategory) => ({
      ...subcategory,
      weight: getGradeStructurePeriodWeight(subcategory, normalizedPeriod)
    }))
  }));
}

function createDefaultGradeStructureDraft() {
  return [
    {
      id: 0,
      name: "Schriftlich",
      weight: 50,
      weights: { h1: 50, h2: 50 },
      subcategories: [{ id: 0, name: "Arbeiten", weight: 100, weights: { h1: 100, h2: 100 } }],
    },
    {
      id: 0,
      name: "Mündlich",
      weight: 50,
      weights: { h1: 50, h2: 50 },
      subcategories: [
        { id: 0, name: "Beteiligung", weight: 80, weights: { h1: 80, h2: 80 } },
        { id: 0, name: "Kurze Lernkontrolle", weight: 20, weights: { h1: 20, h2: 20 } }
      ],
    },
  ];
}

function stripGradeStructureIds(categories) {
  return normalizeGradeStructurePeriodDraft(categories).map((category) => ({
    id: 0,
    name: category.name,
    weight: normalizeGradeStructureWeight(category.weight, 1),
    subcategories: (category.subcategories || []).map((subcategory) => ({
      id: 0,
      name: subcategory.name,
      weight: normalizeGradeStructureWeight(subcategory.weight, 1)
    }))
  }));
}

function normalizeDefaultGradeStructureSetting(value = null) {
  const source = value && typeof value === "object"
    ? value
    : { periodCategories: normalizeGradeStructurePeriodCategoriesPercentDraft(createDefaultGradeStructureDraft()) };
  const normalized = normalizeGradeStructurePeriodCategoriesPercentDraft(source);
  return {
    periodCategories: {
      h1: stripGradeStructureIds(normalized.h1),
      h2: stripGradeStructureIds(normalized.h2)
    }
  };
}

function createDefaultGradeStructureSetting() {
  return normalizeDefaultGradeStructureSetting({
    periodCategories: normalizeGradeStructurePeriodCategoriesPercentDraft(createDefaultGradeStructureDraft())
  });
}

function defaultGradeStructureSettingsEqual(left = null, right = null) {
  return JSON.stringify(normalizeDefaultGradeStructureSetting(left))
    === JSON.stringify(normalizeDefaultGradeStructureSetting(right));
}

function gradeDataTransferHasFiles(dt) {
  if (!dt) {
    return false;
  }
  if (dt.files && dt.files.length > 0) {
    return true;
  }
  const types = dt.types;
  if (!types) {
    return false;
  }
  if (typeof types.includes === "function") {
    return types.includes("Files");
  }
  if (typeof types.contains === "function") {
    return types.contains("Files");
  }
  return Array.from(types).includes("Files");
}

function gradeIsCsvFile(file) {
  if (!file) {
    return false;
  }
  const name = String(file.name || "").toLowerCase();
  const type = String(file.type || "").toLowerCase();
  return name.endsWith(".csv")
    || type.includes("text/csv")
    || type.includes("application/csv")
    || type.includes("application/vnd.ms-excel");
}



function seedTutorialDemoStore(store) {
  const year = store.getActiveSchoolYear();
  if (!year) return null;
  const courseId = store.createCourse(year.id, "Biologie 8a", "#3CB44B", false, false, "Biologie");
  const secondCourseId = store.createCourse(
    year.id,
    "Naturwissenschaften 9b",
    "#E6194B",
    false,
    false,
    "Naturwissenschaften"
  );
  if (!courseId) return null;
  const students = store.replaceGradeStudentsForCourse(courseId, [
    { firstName: "Alex", lastName: "Beispiel", performanceFlair: "P3" },
    { firstName: "Sam", lastName: "Muster", performanceFlair: "P2" },
    { firstName: "Kim", lastName: "Demo", performanceFlair: "P4" },
    { firstName: "Noah", lastName: "Probe", performanceFlair: "P1" }
  ], {
    fileName: "beispiel-namensliste.csv",
    delimiter: ";",
    header: ["Nachname", "Vorname"],
    importedAt: new Date().toISOString()
  });
  const structure = store.saveGradeStructure(
    courseId,
    store.getDefaultGradeStructure().periodCategories
  );
  const secondHalfCategories = Array.isArray(structure?.periodCategories?.h2)
    ? structure.periodCategories.h2
    : [];
  const category = secondHalfCategories.find((item) => item.name === "Mündlich")
    || secondHalfCategories[0]
    || null;
  const subcategory = category?.subcategories?.find((item) => item.name === "Beteiligung")
    || category?.subcategories?.[0]
    || null;
  const assessmentId = store.createGradeAssessment(courseId, {
    title: "Mündliche Mitarbeit",
    mode: "grade",
    weight: 1,
    halfYear: "h2",
    categoryId: category?.id,
    subcategoryId: subcategory?.id
  });
  [12, 10, 14, 8].forEach((value, index) => {
    if (students[index] && assessmentId) {
      store.setGradeEntry(students[index].id, assessmentId, value);
    }
  });
  return courseId;
}

