  async submitCourseStudentsDialog() {
    const id = Number(this.refs.courseStudentsDialogId?.value || 0);
    if (!id || !this.courseDialogDraft) {
      return;
    }
    if (!this.canAccessGradeVault()) {
      this.openGradeVaultDialog(this.isGradeVaultConfigured() ? "unlock" : "setup");
      return;
    }
    let validatedStudents;
    try {
      validatedStudents = this.validateCourseDialogStudents(this.courseDialogDraft.students);
    } catch (error) {
      await this.showInfoMessage(error instanceof Error ? error.message : "Teilnehmendenliste ist ungültig.");
      return;
    }
    const pendingImportMeta = this.courseDialogDraft.importMeta;
    const requiresReplaceConfirm = Boolean(
      pendingImportMeta
      && pendingImportMeta.replacesExisting
      && (this.courseDialogDraft.baseStudentIds || []).length > 0
    );
    if (requiresReplaceConfirm) {
      const confirmed = await this.showConfirmMessage(
        "Vorhandene Schülerliste und zugehörige Noteneinträge dieses Kurses werden ersetzt. Fortfahren?"
      );
      if (!confirmed) {
        return;
      }
      this.courseDialogDraft.confirmedRemovedStudentIds = (
        this.courseDialogDraft.baseStudentIds || []
      ).slice();
    }
    try {
      await this.runGradeCourseMutation(id, () => {
        if (this.getGradeCourseRevision(id) !== Number(this.courseDialogDraft.gradeCourseRevision || 0)) {
          const staleError = new Error("Die Teilnehmerliste wurde zwischenzeitlich geändert. Bitte neu laden.");
          staleError.code = "STALE_GRADE_CONTEXT";
          throw staleError;
        }
        return this.store.replaceGradeStudentsForCourse(id, validatedStudents, pendingImportMeta ? {
          fileName: pendingImportMeta.fileName,
          delimiter: pendingImportMeta.delimiter,
          header: pendingImportMeta.header,
          importedAt: pendingImportMeta.importedAt
        } : null, {
          expectedStudentIds: this.courseDialogDraft.baseStudentIds || [],
          confirmedRemovedStudentIds: this.courseDialogDraft.confirmedRemovedStudentIds || []
        });
      });
    } catch (error) {
      const message = typeof error?.message === "string" ? error.message.trim() : "";
      await this.showInfoMessage(
        message
          ? message
          : "Teilnehmendenliste konnte nicht sicher gespeichert werden."
      );
      return;
    }
    await this.persistExplicitDatabaseSave();
    this.closeCourseStudentsDialog();
    this.renderAll();
  }

