  async deleteCourseById(courseId) {
    const id = Number(courseId) || 0;
    if (!id) return false;
    await this.ensureWorkspacePublicLoaded();
    const baseRevision = this.workspaceController?.getRevision?.() ?? this.workspaceRevision ?? 0;
    if (!await this.showConfirmMessage("Soll dieser Kurs wirklich gelöscht werden?", {
      title: "Kurs löschen", okText: "Kurs wirklich löschen", dangerOk: true
    })) return false;
    const result = await this.executeWorkspaceCommand(WORKSPACE_COMMAND_DELETE_COURSE, {
      courseId: id, destructive: true
    }, { baseRevision });
    if (!result?.ok) {
      await this.showInfoMessage(result?.message || "Kurs konnte nicht gelöscht werden.");
      return false;
    }
    if (Number(this.gradeVaultSession.loadedGradeCourseId) === id) this.gradeVaultSession.loadedGradeCourseId = null;
    if (Number(this.selectedCourseId) === id) this.selectedCourseId = null;
    this.renderAll();
    return true;
  }

